//! Fixed read predicates retained from the reviewed normal API.
// Parameters: owner_id, project_alias, correlation_id, workflow_id, root_id
pub(super) const LINKED_FAMILY_TASKS: &str = "SELECT id, correlation_id FROM forge_agent.coding_tasks WHERE owner_id = $1 AND project_alias = $2 AND (correlation_id = $3 OR workflow_id = $4 OR id = $5 OR repair_root_task_id = $5) LIMIT 64";
// Parameters: owner_id, project_alias, task_ids
pub(super) const CANDIDATE_COMMITS_FOR_TASKS: &str = "SELECT DISTINCT candidate_commit FROM forge_agent.coding_reviews WHERE owner_id = $1 AND project_alias = $2 AND task_id = ANY($3::uuid[]) AND candidate_commit IS NOT NULL";
// Parameters: owner_id, project_alias, task_ids
pub(super) const HOSTED_OBSERVATIONS_FOR_TASKS: &str = "SELECT h.candidate_commit, h.checks FROM forge_agent.coding_hosted_checks h JOIN forge_agent.coding_publications p ON p.publication_id = h.publication_id WHERE h.owner_id = $1 AND h.project_alias = $2 AND p.task_id = ANY($3::uuid[]) ORDER BY h.observed_at ASC, h.observation_id ASC LIMIT 32";
// Parameters: owner_id, project_alias, correlation_ids, main_action, main_commit
pub(super) const STAGE_RESULTS_FOR_CORRELATIONS: &str = "SELECT action_id, stage_index, correlation_id, task_id, job_name, build_number, commit_sha, branch_name, branch_scope, pipeline_scope, logical_stage_id, phase_id, phase_kind, label, status, returncode, duration_ms, tests_passed, tests_failed, tests_skipped, test_summary, error_excerpt, log_sha256, log_byte_count, log_chunk_count, created_at FROM forge_agent.jenkins_stage_results WHERE owner_id = $1 AND project_alias = $2 AND (correlation_id = ANY($3::uuid[]) OR (action_id = $4 AND commit_sha = $5 AND branch_scope = 'main' AND pipeline_scope = 'main')) ORDER BY created_at ASC, action_id ASC, stage_index ASC LIMIT 512";
// Parameters: owner_id, project_alias, correlation_ids, commit_shas, main_action, main_commit
pub(super) const JENKINS_EVENTS_FOR_FAMILY: &str = "SELECT event_kind, job_name, build_number, queue_id, commit_sha, branch, build_result, stage_name, stage_status, occurred_at, sequence, correlation_id, action_id, branch_scope FROM forge_agent.jenkins_events WHERE owner_id = $1 AND project_alias = $2 AND (correlation_id = ANY($3) OR (commit_sha = ANY($4) AND branch_scope IS DISTINCT FROM 'main') OR ($5::uuid IS NOT NULL AND action_id = $5::uuid AND commit_sha = $6::text AND branch_scope = 'main')) ORDER BY sequence ASC LIMIT 512";
// Parameters: fallback_max_rounds, owner_id, project_alias, task_id
pub(super) const REVIEW_WITH_MAX_ROUNDS: &str = "SELECT r.*, coalesce((SELECT (b.policy->>'max_rounds')::integer FROM forge_agent.coding_review_budget b JOIN forge_agent.coding_tasks t ON (t.owner_id, t.project_alias, coalesce(t.repair_root_task_id, t.id)) = (b.owner_id, b.project_alias, b.root_task_id) WHERE t.owner_id = r.owner_id AND t.project_alias = r.project_alias AND t.id = r.task_id), p.max_rounds, $1) AS max_rounds FROM forge_agent.coding_reviews r LEFT JOIN forge_agent.coding_review_policy p USING (owner_id, project_alias) WHERE r.owner_id = $2 AND r.project_alias = $3 AND r.task_id = $4 ORDER BY r.review_no DESC LIMIT 1";
// Parameters: owner_id, project_alias, task_id, attempt_id
pub(super) const PUBLICATION_REQUIRED_GREEN: &str = "SELECT h.required_green FROM forge_agent.coding_publications p JOIN forge_agent.coding_reviews r ON r.review_id = p.review_id AND r.status = 'approved' JOIN LATERAL (SELECT x.required_green FROM forge_agent.coding_hosted_checks x WHERE x.publication_id = p.publication_id AND x.candidate_commit = p.commit_sha ORDER BY x.observed_at DESC, x.observation_id DESC LIMIT 1) h ON true WHERE p.owner_id = $1 AND p.project_alias = $2 AND p.task_id = $3 AND p.attempt_id = $4 AND p.status = 'published' AND p.commit_sha = r.candidate_commit ORDER BY p.created_at DESC LIMIT 1";
